class LLMErrorEnvelope(BaseModel):
    error_type: str; error_message: str; status_code: int | None; retryable: bool

@agent.tool(retries=3)
def risky_tool(ctx: RunContext, q: str) -> str:
    try: return api_call(q)
    except Exception as e:
        raise ToolError(LLMErrorEnvelope(error_type=type(e).__name__, error_message=str(e), status_code=getattr(e, 'status_code', None), retryable=_is_retryable(e)).model_dump_json())
